// Three invoices have line amounts totalling 245, 25 and 0. Collection finds
// every amount for each invoice, including an empty list for invoice 3;
// arithmetic sums them and a second rule flags invoice 1 as large.
//
// Compiled from examples/n3-invoice.n3 with n3-interchange 0.1.4.
// The generated program below runs directly in eyemind and the playground.

// Generated by n3-interchange from examples/n3-invoice.n3.
// Each N3 triple is rdf(Subject, Predicate, Object). Without a log:query
// the conclusions are the triples the forward rules derive.
fact(rdf(iri("https://example.org/invoice#invoice1"), iri("http://www.w3.org/1999/02/22-rdf-syntax-ns#type"), iri("https://example.org/invoice#Invoice")))
fact(rdf(iri("https://example.org/invoice#invoice1"), iri("https://example.org/invoice#line"), iri("https://example.org/invoice#line1")))
fact(rdf(iri("https://example.org/invoice#invoice1"), iri("https://example.org/invoice#line"), iri("https://example.org/invoice#line2")))
fact(rdf(iri("https://example.org/invoice#invoice1"), iri("https://example.org/invoice#line"), iri("https://example.org/invoice#line3")))
fact(rdf(iri("https://example.org/invoice#invoice2"), iri("http://www.w3.org/1999/02/22-rdf-syntax-ns#type"), iri("https://example.org/invoice#Invoice")))
fact(rdf(iri("https://example.org/invoice#invoice2"), iri("https://example.org/invoice#line"), iri("https://example.org/invoice#line4")))
fact(rdf(iri("https://example.org/invoice#invoice2"), iri("https://example.org/invoice#line"), iri("https://example.org/invoice#line5")))
fact(rdf(iri("https://example.org/invoice#invoice3"), iri("http://www.w3.org/1999/02/22-rdf-syntax-ns#type"), iri("https://example.org/invoice#Invoice")))
fact(rdf(iri("https://example.org/invoice#line1"), iri("https://example.org/invoice#amount"), 120))
fact(rdf(iri("https://example.org/invoice#line2"), iri("https://example.org/invoice#amount"), 80))
fact(rdf(iri("https://example.org/invoice#line3"), iri("https://example.org/invoice#amount"), 45))
fact(rdf(iri("https://example.org/invoice#line4"), iri("https://example.org/invoice#amount"), 10))
fact(rdf(iri("https://example.org/invoice#line5"), iri("https://example.org/invoice#amount"), 15))
implies([rdf(Invoice, iri("http://www.w3.org/1999/02/22-rdf-syntax-ns#type"), iri("https://example.org/invoice#Invoice")), findall(Amount, [rdf(Invoice, iri("https://example.org/invoice#line"), Line), rdf(Line, iri("https://example.org/invoice#amount"), Amount)], Amounts), n3_math_sum(Amounts, Total)], rdf(Invoice, iri("https://example.org/invoice#total"), Total))
implies([rdf(Invoice, iri("https://example.org/invoice#total"), Total), n3_math_greaterThan(Total, 200)], rdf(Invoice, iri("http://www.w3.org/1999/02/22-rdf-syntax-ns#type"), iri("https://example.org/invoice#LargeInvoice")))

// N3 built-ins.
// n3_num(T, N): N is the numeric value of the term T.
implied_by(n3_num(T, N), [is_number(T), unify(N, T)])
implied_by(n3_num(T, N), [is_compound(T), unify(T, literal(L, datatype(D))), n3_numeric_type(D), atom_chars(L, Cs), number_chars(N, Cs)])
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#integer'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#decimal'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#double'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#float'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#int'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#long'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#short'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#byte'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#nonNegativeInteger'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#positiveInteger'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#nonPositiveInteger'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#negativeInteger'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#unsignedLong'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#unsignedInt'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#unsignedShort'))
fact(n3_numeric_type('http://www.w3.org/2001/XMLSchema#unsignedByte'))
implied_by(n3_extended(T, [1, V]), n3_num(T, V))
implied_by(n3_extended(literal('INF', datatype(D)), [2, 0]), n3_float_type(D))
implied_by(n3_extended(literal('-INF', datatype(D)), [0, 0]), n3_float_type(D))
fact(n3_float_type('http://www.w3.org/2001/XMLSchema#float'), n3_float_type('http://www.w3.org/2001/XMLSchema#double'))
implied_by(n3_infinite_order(S, O, C), [is_nonvar(S), is_nonvar(O), n3_extended(S, [R1, V1]), n3_extended(O, [R2, V2]), once(or(ne(R1, 1), ne(R2, 1))), compare(C, [R1, V1], [R2, V2])])
implied_by(n3_math_greaterThan(S, O), [n3_num(S, X), n3_num(O, Y), gt(X, Y)])
implied_by(n3_math_greaterThan(S, O), [n3_infinite_order(S, O, C), unify(C, '>')])
// (A B) math:greaterThan true compares A and B.
implied_by(n3_math_greaterThan([A, B], literal('true', datatype('http://www.w3.org/2001/XMLSchema#boolean'))), [n3_num(A, X), n3_num(B, Y), gt(X, Y)])
// n3_nums(L, Ns): the numeric values of a list of terms.
implied_by(n3_nums(L, Ns), [is_nonvar(L), n3_nums_(L, Ns)])
fact(n3_nums_([], []))
implied_by(n3_nums_([T, ...R], [N, ...Ns]), [n3_num(T, N), n3_nums_(R, Ns)])
// n3_result(V, O): an unbound object becomes V, a bound one must equal it
// in value, so 2 and 2.0 agree.
implied_by(n3_result(V, O), [is_var(O), unify(O, V)])
implied_by(n3_result(V, O), [is_nonvar(O), n3_num(O, N), eq(V, N)])
implied_by(n3_math_sum(L, O), [n3_nums(L, Ns), n3_sum(Ns, 0, V), n3_result(V, O)])
// From the left, so floats round as they do written out: ((a + b) + c).
fact(n3_sum([], V, V))
implied_by(n3_sum([N], 0, N), 'true')
implied_by(n3_sum([N, M, ...R], 0, V), [is(A, add(N, M)), n3_sum(R, A, V)])
implied_by(n3_sum([N, ...R], A, V), [not_identical(A, 0), is(B, add(A, N)), n3_sum(R, B, V)])
